import{_ as d,o as e,c as o,a3 as r}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"审批与约束规则","description":"","frontmatter":{},"headers":[],"relativePath":"backend/approval.md","filePath":"backend/approval.md","lastUpdated":1786258579000}'),a={name:"backend/approval.md"};function s(n,t,c,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="审批与约束规则" tabindex="-1">审批与约束规则 <a class="header-anchor" href="#审批与约束规则" aria-label="Permalink to &quot;审批与约束规则&quot;">​</a></h1><p>菜单目录 <code>/approval</code> 下有两个页面，它们解决的是不同的问题，容易混淆：</p><table tabindex="0"><thead><tr><th>页面</th><th>实体</th><th>解决什么</th></tr></thead><tbody><tr><td><strong>审批中心</strong> <code>/approval/review</code></td><td><code>SysReview</code> + <code>SysReviewLog</code></td><td>通用的<strong>单据审批</strong>：某条业务数据要人来批一下</td></tr><tr><td><strong>约束规则</strong> <code>/approval/constraint</code></td><td><code>SysConstraintRule</code> + <code>SysConstraintRuleItem</code></td><td><strong>RBAC 约束引擎</strong>：授权本身合不合规</td></tr></tbody></table><p>再加上第三套：<a href="./workflow">工作流</a> 处理<strong>多步骤、有分支、要等很久</strong>的流程。三者的选型见文末。</p><h2 id="审批中心" tabindex="-1">审批中心 <a class="header-anchor" href="#审批中心" aria-label="Permalink to &quot;审批中心&quot;">​</a></h2><p><code>SysReview</code> 是一张通用审批单，特点是<strong>不绑定具体业务表</strong>——靠三个字段挂到任意业务对象上：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>ReviewCode</code> / <code>ReviewTitle</code></td><td>单号与标题</td></tr><tr><td><code>ReviewType</code></td><td>业务类型（字符串），由接入方定义</td></tr><tr><td><strong><code>EntityType</code> / <code>EntityId</code></strong></td><td><strong>指向被审批的业务对象</strong>（多态关联）</td></tr><tr><td><strong><code>BusinessData</code></strong></td><td><strong>提交时的业务数据快照</strong>（JSON）</td></tr><tr><td><code>ReviewContent</code> / <code>ReviewDescription</code></td><td>内容与说明</td></tr><tr><td><code>ReviewStatus</code></td><td><code>Pending</code> / 已通过 / 已拒绝 等</td></tr><tr><td><code>ReviewResult</code></td><td>审批结果</td></tr><tr><td><code>Priority</code></td><td>优先级</td></tr><tr><td><code>SubmitUserId</code> / <code>SubmitTime</code></td><td>提交人与时间</td></tr><tr><td><code>CurrentReviewUserId</code></td><td>当前处理人</td></tr></tbody></table><p><code>SysReviewLog</code>（按月分表）记录每一步的操作留痕。</p><h3 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to &quot;接入方式&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务写侧</span></span>
<span class="line"><span>   │ 落业务表（状态=待审批）</span></span>
<span class="line"><span>   │ 建 SysReview：EntityType=&quot;Contract&quot;, EntityId=合同Id, BusinessData=快照JSON</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>审批人在审批中心处理 → 通过 / 拒绝 → 写 SysReviewLog</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>业务侧据审批结果回写业务表状态</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title"><code>BusinessData</code> 快照的意义</p><p>审批发生在提交之后，中间业务数据可能已经被改。快照保证<strong>审批人看到的是提交那一刻的内容</strong>，也让事后追溯有据可查（「当时批的是什么」）。</p><p>代价是快照与当前数据可能不一致——通过后回写业务表时要考虑这一点，必要时做冲突检查。</p></div><h3 id="与工作流的分工" tabindex="-1">与工作流的分工 <a class="header-anchor" href="#与工作流的分工" aria-label="Permalink to &quot;与工作流的分工&quot;">​</a></h3><p>审批中心是<strong>单步</strong>的：一个单子、一个（或一组）审批人、一次决定。</p><p>要多级审批、会签、条件分支、超时自动处理、并行分支汇合——用 <a href="./workflow">工作流</a>，它的 <code>UserTask</code> 活动天然支持或签/会签/依次审批与转办加签。</p><h2 id="约束规则引擎" tabindex="-1">约束规则引擎 <a class="header-anchor" href="#约束规则引擎" aria-label="Permalink to &quot;约束规则引擎&quot;">​</a></h2><p>这套东西管的<strong>不是业务数据，而是权限本身</strong>：判断一次授权（或一次操作）是否违反组织的合规规则。</p><p><code>SysConstraintRule</code> 的结构：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td><code>RuleCode</code> / <code>RuleName</code></td><td>规则编码与名称</td><td>—</td></tr><tr><td><code>ConstraintType</code></td><td><strong>约束类型</strong>（见下表）</td><td><code>SSD</code></td></tr><tr><td><code>TargetType</code></td><td>约束对象类型（角色 / 权限 / …）</td><td><code>Role</code></td></tr><tr><td><code>Parameters</code></td><td>规则参数（JSON），不同类型含义不同</td><td>—</td></tr><tr><td><strong><code>ViolationAction</code></strong></td><td><strong>违规时怎么处理</strong>（见下表）</td><td><code>Deny</code></td></tr><tr><td><code>Priority</code></td><td>优先级</td><td><code>0</code></td></tr><tr><td><code>EffectiveTime</code> / <code>ExpirationTime</code></td><td>生效时间窗</td><td>—</td></tr><tr><td><code>Status</code></td><td>启停</td><td><code>Enabled</code></td></tr></tbody></table><p><code>SysConstraintRuleItem</code> 是规则的目标项集合（如「这三个角色互斥」里的那三个角色）。</p><h3 id="八类约束" tabindex="-1">八类约束 <a class="header-anchor" href="#八类约束" aria-label="Permalink to &quot;八类约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>值</th><th>含义</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>SSD</strong> 静态职责分离</td><td>0</td><td>一个用户<strong>不能同时被授予</strong>这组角色</td><td>「制单员」与「审核员」不能是同一人</td></tr><tr><td><strong>DSD</strong> 动态职责分离</td><td>1</td><td>可以都有，但<strong>同一会话内不能同时激活</strong></td><td>平时可切换身份，单次操作只能用一个</td></tr><tr><td><strong>互斥约束</strong></td><td>2</td><td>指定对象互相排斥</td><td>两个权限不能共存</td></tr><tr><td><strong>基数约束</strong></td><td>3</td><td>数量上限</td><td>「超级管理员最多 3 人」</td></tr><tr><td><strong>先决条件</strong></td><td>4</td><td>授予 A 前必须先有 B</td><td>给「财务审批」前必须先有「财务查看」</td></tr><tr><td><strong>时间约束</strong></td><td>5</td><td>只在特定时间窗内有效</td><td>临时权限只在项目期内</td></tr><tr><td><strong>位置约束</strong></td><td>6</td><td>按 IP 限制</td><td>财务操作只能在办公网</td></tr><tr><td><strong>自定义</strong></td><td>99</td><td>扩展点</td><td>—</td></tr></tbody></table><h3 id="四种违规处理" tabindex="-1">四种违规处理 <a class="header-anchor" href="#四种违规处理" aria-label="Permalink to &quot;四种违规处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>值</th><th>效果</th></tr></thead><tbody><tr><td><code>Deny</code> 拒绝</td><td>0</td><td>直接阻断，授权/操作失败</td></tr><tr><td><code>Warning</code> 警告</td><td>1</td><td>放行但提示</td></tr><tr><td><code>Log</code> 记录日志</td><td>2</td><td>静默放行，只留痕</td></tr><tr><td><strong><code>RequireApproval</code> 转审批</strong></td><td>3</td><td><strong>转成审批流程</strong>，批了才生效</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">上线新规则的姿势</p><p>直接上 <code>Deny</code> 风险很大——存量数据里往往已经有一批违规状态，一开就把人挡在外面。</p><p>推荐路径：先用 <code>Log</code> 跑一段时间，从日志里看有多少违规、都是谁；清理完存量后改成 <code>Warning</code> 观察；确认干净了再切 <code>Deny</code>。</p></div><div class="warning custom-block"><p class="custom-block-title">违规检查发生在授权时，不是登录时</p><p>约束规则参与的是「能不能把这个角色/权限授给这个人」以及请求期的判定链。已经授出去的存量违规组合<strong>不会自动回收</strong>——要清理得跑一次巡检。</p></div><h2 id="三套机制怎么选" tabindex="-1">三套机制怎么选 <a class="header-anchor" href="#三套机制怎么选" aria-label="Permalink to &quot;三套机制怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的需求</th><th>用哪套</th></tr></thead><tbody><tr><td>一条业务数据要人批一下，一步搞定</td><td><strong>审批中心</strong> <code>SysReview</code></td></tr><tr><td>多级/会签/分支/超时/并行的长流程</td><td><strong><a href="./workflow">工作流</a></strong></td></tr><tr><td>「谁不能同时拥有哪些角色」这类合规规则</td><td><strong>约束规则引擎</strong></td></tr><tr><td>用户主动申请某个权限，管理员审批</td><td><strong>权限申请</strong>（<code>SysPermissionRequest</code>，见 <a href="./permission">权限模型</a>）</td></tr></tbody></table><p>它们可以组合：约束规则的 <code>RequireApproval</code> 就是把违规转成审批单；工作流的 <code>UserTask</code> 也可以承载复杂的权限审批流。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./permission">权限模型</a>：约束规则在鉴权判定链里的位置、权限申请与委托</li><li><a href="./workflow">工作流</a>：多步骤流程</li><li><a href="./logging">审计日志</a>：权限变更留痕</li><li><a href="./data-model#权限与授权">数据模型</a>：相关表结构</li></ul>`,30)])])}const b=d(a,[["render",s]]);export{g as __pageData,b as default};
